<?php $__currentLoopData = $variants; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><button type="button" class="ret-product-choice" data-id="<?php echo e($v->id); ?>" data-name="<?php echo e($v->product->name); ?> / <?php echo e($v->sku); ?>" data-price="<?php echo e($v->price); ?>" data-stock="<?php echo e($v->stock); ?>"><strong><?php echo e($v->product->name); ?></strong><small><?php echo e($v->sku); ?></small><small><?php echo e(t('Stock','স্টক')); ?>: <?php echo e($v->stock); ?></small><strong><?php echo e(number_format($v->price,2)); ?></strong></button><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
</div></div><div class="ret-card"><h3><?php echo e(t('Current Cart','বর্তমান কার্ট')); ?></h3><p class="ret-help"><?php echo e(t('Click items to add to cart','পণ্যতে ক্লিক করে কার্টে যোগ করুন')); ?></p><div id="pos-cart"></div><hr class="ret-divider"><div class="ret-field"><label><?php echo e(t('Discount Amount','ছাড়ের পরিমাণ')); ?></label><input name="discount" class="ret-input" type="number" value="0" min="0" step=".01"></div><div class="ret-field"><label><?php echo e(t('Coupon Code','কুপন কোড')); ?></label><input name="coupon_code" class="ret-input"></div><div class="ret-field"><label><?php echo e(t('Customer Name','কাস্টমারের নাম')); ?></label><input name="customer_name" class="ret-input"></div><div class="ret-field"><label><?php echo e(t('Receive Now','এখন গ্রহণ')); ?></label><input name="pay_amount" type="number" class="ret-input" value="0" min="0" step=".01"></div><div class="ret-field"><label><?php echo e(t('Payment Method','পেমেন্ট পদ্ধতি')); ?></label><select class="ret-input" name="payment_method"><option value="cash">Cash</option><option value="bank">Bank</option></select></div><div style="font-size:19px;padding:15px 0"><strong><?php echo e(t('Subtotal','সাবটোটাল')); ?>: <span id="pos-total">0.00</span></strong></div><button class="ret-btn" type="submit"><?php echo e(t('Complete Sale','বিক্রয় সম্পন্ন')); ?></button></div></div></form>
<script>
document.addEventListener('DOMContentLoaded',()=>{
const holder=document.getElementById('pos-cart'),buttons=[...document.querySelectorAll('.ret-product-choice')],basket=new Map();
function escapeHtml(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');}
function render(){let total=0,n=0;holder.replaceChildren();for(const [id,row] of basket){total+=row.price*row.qty;const div=document.createElement('div');div.style.cssText='padding:10px 0;border-bottom:1px solid var(--rp-border)';div.innerHTML=`<strong>${escapeHtml(row.name)}</strong> <span>${row.price}</span><div style="display:flex;align-items:center;gap:8px;margin-top:7px"><input type="hidden" name="items[${n}][variant_id]" value="${id}"><input class="ret-input" style="width:100px" type="number" min="1" max="${row.stock}" step="1" name="items[${n}][quantity]" value="${row.qty}"><button class="ret-btn alt" type="button">×</button></div>`;n++;div.querySelector('input[type=number]').oninput=e=>{row.qty=Math.max(1,Math.min(row.stock,Number(e.target.value)||1));document.getElementById('pos-total').textContent=[...basket.values()].reduce((a,x)=>a+x.qty*x.price,0).toFixed(2);};div.querySelector('button').onclick=()=>{basket.delete(id);render()};holder.append(div);}document.getElementById('pos-total').textContent=total.toFixed(2);}
buttons.forEach(b=>b.onclick=()=>{const id=b.dataset.id,stock=Number(b.dataset.stock);if(stock<1){alert('Out of stock');return;}let row=basket.get(id);if(row){if(row.qty<stock)row.qty++;}else basket.set(id,{name:b.dataset.name,price:Number(b.dataset.price),stock,qty:1});render()});
document.getElementById('pos-search').oninput=e=>buttons.forEach(b=>b.hidden=!b.dataset.name.toLowerCase().includes(e.target.value.toLowerCase()));
});
</script>
</main></div>
